template <typename Msg>
std::vector<std::uint8_t> pack(const Msg& m) {
  std::vector<std::uint8_t> b;
  b.reserve(64);
  Writer w(b);
  w.u16(Msg::kId);
  const size_t lenSlot = b.size();
  w.u16(0);
  m.serialize(w);
  const std::uint16_t len =
      static_cast<std::uint16_t>(b.size() - lenSlot - 2);
  b[lenSlot] = static_cast<std::uint8_t>(len & 0xFF);
  b[lenSlot + 1] = static_cast<std::uint8_t>(len >> 8);
  return b;
}

struct PacketView {
  std::uint16_t id = 0;
  Reader body{nullptr, 0};
  bool ok = false;
};

inline PacketView view(const std::uint8_t* data, size_t len) {
  PacketView pv;
  if (data == nullptr || len < 4) return pv;
  Reader h(data, len);
  std::uint16_t id = 0, plen = 0;
  if (!h.u16(id) || !h.u16(plen)) return pv;
  if (len - 4 != plen) return pv;
  pv.id = id;
  pv.body = Reader(data + 4, plen);
  pv.ok = true;
  return pv;
}

